<script setup lang="ts">
import { PARTNER_AGENCIES, SERVICE_CATEGORIES } from '@/utils/caseOptions';
import { computed, nextTick, ref, watch } from 'vue';
import { Head, Link } from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import PlanningForm from '@/Components/PlanningForm.vue';
import InterventionOutcomeForm from '@/Components/InterventionOutcomeForm.vue';
import StatusBadge from '@/Components/UI/StatusBadge.vue';
import FormField from '@/Components/UI/FormField.vue';
import Modal from '@/Components/Modal.vue';
import { usePlanningWorkspace } from '@/composables/usePlanningWorkspace';
import type { PlanningData, PlanningField, PlanningValue, HandoverRecord, PlanIntervention } from '@/types/planning';

const props=defineProps<{caseRecord:{id:number;case_number:string;status:string};currentUserId:number;canManage:boolean;canReview:boolean;canTransfer:boolean;transferCandidates:{id:number;name:string;role:string}[];serviceProviders?:{id:number;name:string;service_type:string}[]}>();
const {data,selectedId,selected,isAuthor,editable,busy,loaded,disabled,refreshRequired,message,error,errors,errorSummary,forms,dirtyKeys,form,load,save,errorsFor}=usePlanningWorkspace(props.caseRecord.id,props.currentUserId);
const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const human=(text:string)=>text.replaceAll('_',' ');
const date=(text:string|null|undefined)=>text?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(`${text.slice(0,10)}T00:00:00Z`)):'Not set';
const option=(value:PlanningValue,label?:string)=>({value,label:label??human(String(value))});
const priorities=['low','normal','high','urgent'].map(value=>option(value));
const domains=['safety_protection','health','reproductive_health','mental_health_psychosocial','education','family_strengthening','economic_social_protection','legal_justice','child_development','community_support','reintegration','aftercare','other'].map(value=>option(value));
const createDefaults:PlanningData={plan_date:day,overall_objective:'',review_due_at:'',previous_plan_id:null};
const goalDefaults:PlanningData={domain:'safety_protection',need_problem:'',goal_statement:'',priority:'normal',target_date:''};
const interventionDefaults:PlanningData={case_plan_goal_id:'',activity:'',service_category:'',service_provider_id:null,responsible_office:'',start_date:'',target_date:'',priority:'normal',expected_outcome:'',origin_type:'',origin_id:'',operational_record_type:'',operational_record_id:''};
const reviewDefaults:PlanningData={review_date:day,overall_progress:'on_track',revision_required:false,recommendation:'',next_review_at:''};
const aftercareDefaults:PlanningData={case_plan_id:null,required:false,responsible_office:'',initial_follow_up_at:'',basis:''};
const reintegrationDefaults:PlanningData={case_plan_id:null,applicable:false,responsible_office:'',target_date:'',review_at:'',basis:''};
const transferDefaults:PlanningData={originating_office:'',receiving_office:'',receiving_worker_id:'',reason:'',continuity_notes:''};
form('newPlan',createDefaults);form('aftercare',aftercareDefaults);form('reintegration',reintegrationDefaults);form('transfer',transferDefaults);
function formKey(kind:string){return `${kind}:${selected.value?.plan.id??0}`;}
function model(kind:string,defaults:PlanningData){return computed({get:()=>form(formKey(kind),defaults),set:value=>{forms[formKey(kind)]=value;}});}
const goal=model('goal',goalDefaults);const intervention=model('intervention',interventionDefaults);const review=model('review',reviewDefaults);const comments=model('comments',{comments:''});
const reviewComments=computed({get:()=>String(comments.value.comments??''),set:value=>{comments.value={comments:value};}});
const activePanel=ref<HTMLElement|null>(null);
const showCreate=ref(false);const activeView=ref(new URLSearchParams(window.location.search).get('activity')==='continuity'?'continuity':'goals');watch(activeView,()=>void nextTick(()=>{activePanel.value?.scrollIntoView({block:'start'});activePanel.value?.focus({preventScroll:true});}));watch(loaded,ready=>{if(ready)showCreate.value=!data.value.plans.length;});
const views=computed(()=>[{key:'goals',label:'Goals & objectives'},{key:'interventions',label:'Interventions'},{key:'review',label:'Review & history'},{key:'continuity',label:'Aftercare & reintegration'},...(props.canTransfer?[{key:'handover',label:'Formal handover'}]:[])]);
const planOptions=computed(()=>[option(null,'No linked plan'),...data.value.plans.map(entry=>option(entry.plan.id,`Version ${entry.plan.version} - ${human(entry.plan.status)}`))]);
const createFields=computed<PlanningField[]>(()=>[
 {key:'plan_date',label:'Plan date',kind:'date',required:true},{key:'review_due_at',label:'Review due date',kind:'date'},
 {key:'overall_objective',label:'Overall objective',kind:'textarea',required:true,wide:true,hint:'Record the intended change. Avoid repeating sensitive source-assessment narratives.'},
 {key:'previous_plan_id',label:'Base on existing plan (optional)',kind:'select',options:[option(null,'New planning cycle'),...data.value.plans.filter(entry=>['active','under_review','completed'].includes(entry.plan.status)).map(entry=>option(entry.plan.id,`Version ${entry.plan.version} - ${human(entry.plan.status)}`))],wide:true},
]);
const goalFields:PlanningField[]=[{key:'domain',label:'Domain',kind:'select',options:domains},{key:'priority',label:'Priority',kind:'select',options:priorities},{key:'need_problem',label:'Need / problem',kind:'textarea',required:true,max:500,wide:true},{key:'goal_statement',label:'Goal statement',kind:'textarea',required:true,wide:true},{key:'target_date',label:'Target date',kind:'date'}];
const interventionFields=computed<PlanningField[]>(()=>[
 {key:'case_plan_goal_id',label:'Select goal',kind:'select',required:true,wide:true,options:[option('','Select goal'),...(selected.value?.goals??[]).map(item=>option(item.id,item.goal_statement))]},
 {key:'activity',label:'Agreed activity',kind:'textarea',required:true,wide:true},{key:'service_category',label:'Service category',kind:'choice',choices:SERVICE_CATEGORIES,required:true},{key:'service_provider_id',label:'Service provider',kind:'select',options:[option(null,'No provider selected'),...(props.serviceProviders??[]).map(provider=>option(provider.id,provider.name))]},
 {key:'responsible_office',label:'Responsible office',kind:'choice',choices:PARTNER_AGENCIES,max:180},{key:'priority',label:'Priority',kind:'select',options:priorities},{key:'start_date',label:'Start date',kind:'date'},{key:'target_date',label:'Target date',kind:'date'},{key:'expected_outcome',label:'Expected outcome',kind:'textarea',wide:true},
 {key:'operational_record_type',label:'Execution record type',kind:'select',options:[option('','No linked execution record'),...['task','referral','mdt_action','risk_reassessment_request'].map(value=>option(value))],hint:'Link an existing authorized record only when it owns execution.'},
 ...(intervention.value.operational_record_type?[{key:'operational_record_id',label:'Existing record ID',kind:'number' as const,required:true}]:[]),
]);
const reviewFields:PlanningField[]=[{key:'review_date',label:'Review date',kind:'date',required:true},{key:'overall_progress',label:'Overall progress',kind:'select',options:['on_track','delayed','blocked','completed'].map(value=>option(value))},{key:'next_review_at',label:'Next review date',kind:'date'},{key:'revision_required',label:'Revision/new version required',kind:'checkbox'},{key:'recommendation',label:'Professional recommendation',kind:'textarea',wide:true}];
const aftercareFields=computed<PlanningField[]>(()=>[{key:'case_plan_id',label:'Linked aftercare plan',kind:'select',options:planOptions.value},{key:'required',label:'Aftercare required',kind:'checkbox'},{key:'responsible_office',label:'Responsible office',kind:'choice',choices:PARTNER_AGENCIES,max:180},{key:'initial_follow_up_at',label:'Initial follow-up date',kind:'date'},{key:'basis',label:'Basis / continuity rationale',kind:'textarea',wide:true}]);
const reintegrationFields=computed<PlanningField[]>(()=>[{key:'case_plan_id',label:'Linked reintegration plan',kind:'select',options:planOptions.value},{key:'applicable',label:'Applicable to this case',kind:'checkbox'},{key:'responsible_office',label:'Responsible office',kind:'choice',choices:PARTNER_AGENCIES,max:180},{key:'target_date',label:'Target date',kind:'date'},{key:'review_at',label:'Review date',kind:'date'},{key:'basis',label:'Basis / professional rationale',kind:'textarea',wide:true}]);
const transferFields=computed<PlanningField[]>(()=>[{key:'originating_office',label:'Originating office',required:true,max:180},{key:'receiving_office',label:'Receiving office',required:true,max:180},{key:'receiving_worker_id',label:'Receiving worker',kind:'select',options:[option('','Receiving worker (optional)'),...props.transferCandidates.map(worker=>option(worker.id,`${worker.name} · ${human(worker.role)}`))],wide:true},{key:'reason',label:'Reason for handover',kind:'textarea',required:true,wide:true},{key:'continuity_notes',label:'Minimum-necessary continuity notes',kind:'textarea',wide:true}]);
async function createPlan(){if(await save({method:'post',url:route('cases.plans.store',props.caseRecord.id),body:forms.newPlan,formKey:'newPlan',defaults:createDefaults,success:'Draft plan created.',selectCreated:true}))showCreate.value=false;}
function addGoal(){if(selected.value)return save({method:'post',url:route('cases.plans.goals.store',[props.caseRecord.id,selected.value.plan.id]),body:goal.value,formKey:formKey('goal'),defaults:goalDefaults,success:'Goal added.'});}
function addIntervention(){if(selected.value)return save({method:'post',url:route('cases.plans.interventions.store',[props.caseRecord.id,selected.value.plan.id]),body:{...intervention.value,case_plan_goal_id:Number(intervention.value.case_plan_goal_id),operational_record_id:intervention.value.operational_record_id||null,origin_id:intervention.value.origin_id||null},formKey:formKey('intervention'),defaults:interventionDefaults,success:'Intervention added.'});}
function addReview(){if(selected.value)return save({method:'post',url:route('cases.plans.reviews.store',[props.caseRecord.id,selected.value.plan.id]),body:review.value,formKey:formKey('review'),defaults:reviewDefaults,success:'Formal review recorded.'});}
const serviceSearch=ref('');const serviceStatus=ref('');const openOutcomes=ref<Record<number,boolean>>({});
const execution=(action:PlanIntervention)=>action.operational_status??action.progress;
const serviceStatuses=computed(()=>[...new Set((selected.value?.interventions??[]).map(execution))].sort());
const shownServices=computed(()=>(selected.value?.interventions??[]).filter(action=>(!serviceStatus.value||execution(action)===serviceStatus.value)&&(!serviceSearch.value.trim()||[action.activity,action.service_category,action.responsible_office,action.provider_name].some(value=>value?.toLocaleLowerCase().includes(serviceSearch.value.trim().toLocaleLowerCase())))));
watch(selectedId,()=>{serviceSearch.value='';serviceStatus.value='';});
const outcomeKey=(id:number)=>`outcome:${id}`;
function outcomeData(action:PlanIntervention){return form(outcomeKey(action.id),{...(!action.operational_record_type?{progress:action.progress}:{}),outcome_status:action.outcome_status??'',actual_outcome:action.actual_outcome??'',barriers:action.barriers??'',next_action:action.next_action??''});}
function saveOutcome(action:PlanIntervention){if(!selected.value)return;const body={...outcomeData(action)};return save({method:'patch',url:route('cases.plans.interventions.update',[props.caseRecord.id,selected.value.plan.id,action.id]),body,formKey:outcomeKey(action.id),defaults:body,success:'Service outcome recorded.'});}
const pastTarget=(action:PlanIntervention)=>Boolean(action.target_date&&action.target_date.slice(0,10)<day&&!['completed','cancelled','discontinued'].includes(execution(action).toLowerCase()));
function continuity(kind:'aftercare'|'reintegration'){return save({method:'post',url:route(`cases.${kind}.store`,props.caseRecord.id),body:forms[kind],formKey:kind,defaults:kind==='aftercare'?aftercareDefaults:reintegrationDefaults,success:kind==='aftercare'?'Aftercare continuity record saved.':'Reintegration record saved.'});}
function saveTransfer(){return save({method:'post',url:route('cases.transfers.store',props.caseRecord.id),body:{...forms.transfer,receiving_worker_id:forms.transfer.receiving_worker_id||null},formKey:'transfer',defaults:transferDefaults,success:'Handover draft saved.'});}
interface PendingChange {title:string;status:string;transfer?:HandoverRecord}
const pending=ref<PendingChange|null>(null);
function ask(status:string,title:string,transfer?:HandoverRecord){
 if(disabled.value)return;
 if(!transfer&&(['goal','intervention','review'].some(kind=>dirtyKeys.value.includes(formKey(kind)))||(selected.value?.interventions??[]).some(action=>dirtyKeys.value.includes(outcomeKey(action.id))))){
  error.value='Save unfinished work in the selected plan before changing its workflow status.';void nextTick(()=>errorSummary.value?.focus());return;
 }
 pending.value={title,status,transfer};
}
let approvedChange:PendingChange|null=null;
function cancelChange(){approvedChange=null;pending.value=null;}
function applyChange(){if(!pending.value||disabled.value)return;approvedChange=pending.value;pending.value=null;}
async function applyAfterClose(){const change=approvedChange;approvedChange=null;if(!change||disabled.value)return;
 if(change.transfer){await save({method:'patch',url:route('cases.transfers.transition',[props.caseRecord.id,change.transfer.id]),body:{status:change.status},success:`Transfer moved to ${human(change.status)}.`});return;}
 if(selected.value)await save({method:'patch',url:route('cases.plans.transition',[props.caseRecord.id,selected.value.plan.id]),body:{status:change.status,comments:comments.value.comments||null},formKey:formKey('comments'),defaults:{comments:''},success:`Plan moved to ${human(change.status)}.`});
}
function handoverActions(item:HandoverRecord){return ({draft:[['requested','Request']],requested:[['endorsed','Endorse'],['returned_for_clarification','Return for clarification']],endorsed:[['accepted','Accept']],accepted:[['completed','Complete handover']],returned_for_clarification:[['requested','Request']]} as Record<string,string[][]>)[item.status]??[];}
</script>

<template>
 <Head :title="`Plan & continuity - ${caseRecord.case_number}`"/>
 <AuthenticatedLayout>
  <div class="planning-page space-y-5 p-4 sm:p-6">
   <header class="planning-banner rounded-lg border border-brand-900 bg-brand-800 p-3 text-white sm:p-4">
    <Link :href="route('cases.show',caseRecord.id)" class="inline-flex min-h-11 items-center text-sm font-semibold text-white underline underline-offset-4">Back to case</Link>
    <div class="mt-1 flex flex-wrap items-start justify-between gap-4"><div class="min-w-0"><h1 class="mt-1 text-xl font-semibold sm:text-2xl">Case plan</h1><p class="mt-2 text-sm leading-6">{{caseRecord.case_number}} - {{human(caseRecord.status)}}</p></div><div class="flex flex-wrap gap-2"><button type="button" class="ui-button" :disabled="busy" @click="load">Refresh</button><button v-if="canManage" type="button" class="ui-button" :disabled="disabled" :aria-expanded="showCreate" aria-controls="new-plan-panel" @click="showCreate=!showCreate">{{showCreate?'Hide new cycle':'Start a new cycle'}}</button></div></div>
   </header>
   <p v-if="busy" role="status" class="rounded-md border border-brand-200 bg-brand-50 p-3 text-sm text-brand-900">Working on this planning workspace...</p>
   <p v-if="message" role="status" class="rounded-md border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900">{{message}}</p>
   <div v-if="error" ref="errorSummary" role="alert" tabindex="-1" class="rounded-md border border-rose-300 bg-rose-50 p-4 text-sm text-rose-900"><p class="font-semibold">{{error}}</p><ul v-if="Object.keys(errors).length" class="mt-2 list-inside list-disc"><li v-for="(value,key) in errors" :key="key">{{value}}</li></ul></div>
   <p v-if="dirtyKeys.length" class="rounded-md border border-amber-300 bg-kalinga-warm p-3 text-sm text-amber-950">{{dirtyKeys.length}} unfinished form(s) retained on this page. Save online before closing; navigation can be cancelled. Planning edits are not available offline.</p>
   <p v-if="refreshRequired" class="ui-muted">Further changes are paused until Refresh succeeds. Review saved records before submitting anything again.</p>
   <div v-if="canManage&&showCreate" id="new-plan-panel"><PlanningForm id="new-plan" title="Start a plan cycle" description="A new draft does not replace the current plan until an independent authorized reviewer activates it." v-model="forms.newPlan" :fields="createFields" :busy="disabled" submit-label="Create draft" :errors="errorsFor('newPlan')" @submit="createPlan"/></div>
   <div v-if="loaded" class="grid min-w-0 gap-5 xl:grid-cols-[14rem_minmax(0,1fr)]">
    <nav aria-label="Plan versions" class="ui-panel self-start border-t-4 border-t-brand-600 p-3"><h2 class="ui-section-title p-1">Plan versions</h2><p class="ui-muted hidden px-1 xl:block">Choose the record to work on.</p><div class="mt-2 xl:hidden"><label for="planning-version" class="sr-only">Plan version</label><select id="planning-version" v-model="selectedId" :disabled="busy" class="ui-field"><option v-for="entry in data.plans" :key="entry.plan.id" :value="entry.plan.id">Version {{entry.plan.version}} - {{human(entry.plan.status)}}</option><option v-if="!data.plans.length" :value="null">No planning cycle yet</option></select></div><div class="mt-3 hidden gap-2 xl:grid"><button v-for="entry in data.plans" :key="entry.plan.id" type="button" :disabled="busy" :aria-current="selected?.plan.id===entry.plan.id?'true':undefined" class="min-h-16 min-w-0 rounded-md border p-3 text-left" :class="selected?.plan.id===entry.plan.id?'border-brand-600 bg-brand-50 text-brand-900':'border-slate-200 bg-white text-slate-800'" @click="selectedId=entry.plan.id"><span class="block text-sm font-semibold">Version {{entry.plan.version}} · {{human(entry.plan.status)}}</span><span class="mt-1 block text-xs">{{entry.plan.is_current?'Current plan':'Historical / draft'}} - {{entry.goals.length}} goal(s)</span></button></div><p v-if="!data.plans.length" class="ui-muted p-1">No planning cycle yet.</p></nav>
    <div class="min-w-0 space-y-4">
     <section v-if="selected" class="ui-panel border-l-4 border-l-[#83cbdd] p-4 sm:p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="ui-section-title">Version {{selected.plan.version}} · {{human(selected.plan.status)}}</h2><p class="ui-muted mt-1">Plan date {{date(selected.plan.plan_date)}} - review due {{date(selected.plan.review_due_at)}}</p><p class="mt-1 text-xs text-slate-600">Author #{{selected.plan.authored_by}}<span v-if="selected.plan.previous_plan_id"> - follows plan #{{selected.plan.previous_plan_id}}</span></p></div><StatusBadge :label="selected.plan.is_current?'Current plan':human(selected.plan.status)" :tone="selected.plan.is_current?'success':'brand'"/></div><article class="mt-4"><h3 class="text-sm font-semibold text-slate-900">Overall objective</h3><p class="mt-1 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{{selected.plan.overall_objective||selected.plan.summary}}</p></article><div class="mt-4 flex flex-wrap gap-2"><StatusBadge :label="`${selected.goals.length} goals`"/><StatusBadge :label="`${selected.interventions.length} interventions`" tone="info"/></div></section>
     <nav aria-label="Planning activities" class="rounded-lg border border-brand-200 bg-brand-100 p-1"><div class="p-2 sm:hidden"><label for="planning-activity" class="mb-1 block text-xs font-semibold text-brand-900">Planning activity</label><select id="planning-activity" v-model="activeView" class="ui-field"><option v-for="view in views" :key="view.key" :value="view.key">{{view.label}}</option></select></div><div class="hidden gap-1 sm:grid sm:grid-cols-2 lg:flex lg:flex-wrap"><button v-for="view in views" :key="view.key" type="button" class="min-h-11 rounded-md px-3 py-2 text-left text-sm font-semibold" :class="activeView===view.key?'bg-brand-800 text-white':'text-brand-900 hover:bg-brand-50'" :aria-current="activeView===view.key?'page':undefined" @click="activeView=view.key">{{view.label}}</button></div></nav>
     <section v-if="activeView==='goals'" aria-label="Goals and objectives" ref="activePanel" tabindex="-1" class="space-y-4">
      <div v-if="selected" class="ui-panel overflow-hidden"><header class="ui-panel-header bg-brand-50"><h2 class="ui-section-title">Case plan goals and objectives</h2><span class="text-sm text-brand-900">{{selected.goals.length}} recorded</span></header><div v-if="!selected.goals.length" class="p-5 text-sm text-slate-600">No goals recorded in this version. Add the agreed needs and intended changes.</div><div v-else class="divide-y divide-slate-200"><article v-for="item in selected.goals" :key="item.id" class="grid gap-3 p-4 sm:grid-cols-[minmax(0,1fr)_10rem]"><div class="min-w-0"><p class="text-xs font-semibold uppercase tracking-wide text-brand-800">{{human(item.domain)}}</p><h3 class="mt-1 break-words text-sm font-semibold text-slate-900">{{item.goal_statement}}</h3><p class="mt-1 whitespace-pre-wrap break-words text-sm leading-6 text-slate-600">{{item.need_problem}}</p></div><div class="space-y-2 text-sm"><StatusBadge :label="human(item.status)" tone="success"/><p>Target {{date(item.target_date)}}</p><p class="text-xs text-slate-600">Priority {{human(item.priority)}} - {{selected.interventions.filter(action=>action.case_plan_goal_id===item.id).length}} intervention(s)</p></div></article></div></div>
      <PlanningForm v-if="editable" id="goal" title="Add goal" v-model="goal" :fields="goalFields" :busy="disabled" submit-label="Save goal" :errors="errorsFor(formKey('goal'))" @submit="addGoal"/>
      <p v-if="!selected" class="ui-panel p-5 text-sm text-slate-600">Start a plan cycle before recording goals.</p>
     </section>
     <section v-else-if="activeView==='interventions'" aria-label="Interventions" ref="activePanel" tabindex="-1" class="space-y-4">
      <p class="rounded-md border border-sky-200 bg-sky-50 p-3 text-sm leading-6 text-sky-950">Record intended activities and outcomes here. A linked task, referral or MDT action remains the authority for execution status.</p>
      <div class="ui-panel p-4"><div class="grid gap-3 sm:grid-cols-[minmax(0,1fr)_12rem_auto]"><FormField id="service-search" label="Search this plan's services"><input id="service-search" v-model="serviceSearch" autocomplete="off" type="search" class="ui-field"></FormField><FormField id="service-status" label="Execution status"><select id="service-status" v-model="serviceStatus" class="ui-field"><option value="">All recorded statuses</option><option v-for="status in serviceStatuses" :key="status" :value="status">{{human(status)}}</option></select></FormField><button type="button" class="ui-button self-end" @click="serviceSearch='';serviceStatus=''">Clear filters</button></div><p class="mt-3 text-xs text-slate-600">{{shownServices.length}} shown of {{selected?.interventions.length??0}} intervention(s) in this version.</p></div>
      <article v-for="action in shownServices" :key="action.id" class="ui-panel overflow-hidden"><header class="ui-panel-header bg-brand-50"><div class="min-w-0"><p class="text-xs font-semibold uppercase tracking-wide text-brand-800">{{action.service_category}}</p><h2 class="ui-section-title mt-1 break-words">{{action.activity||`${action.service_category} intervention`}}</h2></div><StatusBadge :label="human(execution(action))" tone="info"/></header><div class="space-y-3 p-4 sm:p-5"><div v-if="!action.activity" class="rounded-md border border-amber-200 bg-kalinga-warm p-3 text-sm text-amber-950"><p>Activity not recorded.</p><p v-if="action.goal" class="mt-2 whitespace-pre-wrap break-words">{{action.goal}}</p></div><dl class="grid gap-3 text-sm sm:grid-cols-2 lg:grid-cols-3"><div><dt class="text-xs font-medium text-slate-600">Provider</dt><dd class="mt-1 text-slate-900">{{action.provider_name||'Provider not recorded'}}</dd></div><div><dt class="text-xs font-medium text-slate-600">Responsible office</dt><dd class="mt-1 text-slate-900">{{action.responsible_office||'Not recorded'}}</dd></div><div><dt class="text-xs font-medium text-slate-600">Recorded target</dt><dd class="mt-1 text-slate-900">{{date(action.target_date)}} <StatusBadge v-if="pastTarget(action)" label="Past recorded target" tone="warning"/></dd></div></dl>
       <p v-if="action.operational_record_type" class="rounded-md border border-sky-200 bg-sky-50 p-3 text-sm font-semibold text-sky-950">Execution status: {{action.operational_status||'Unavailable'}} - source: {{human(action.operational_record_type)}} #{{action.operational_record_id}}</p><p v-else class="text-sm text-slate-700">Execution progress is recorded in this plan.</p>
       <div class="rounded-md border border-slate-200 bg-slate-50 p-3"><p class="text-sm font-semibold text-slate-900">Plan outcome: {{action.outcome_status?human(action.outcome_status):'Not yet recorded'}}</p><p v-if="action.expected_outcome" class="ui-muted mt-2">Expected outcome: {{action.expected_outcome}}</p><p v-if="action.actual_outcome" class="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{{action.actual_outcome}}</p><p v-if="action.barriers" class="ui-muted mt-2 whitespace-pre-wrap break-words">Barriers: {{action.barriers}}</p><p v-if="action.next_action" class="ui-muted mt-2 whitespace-pre-wrap break-words">Next action: {{action.next_action}}</p></div>
       <button v-if="canManage&&isAuthor&&selected?.plan.status==='active'" type="button" class="ui-button-primary" :disabled="disabled" :aria-expanded="Boolean(openOutcomes[action.id])" :aria-controls="`outcome-editor-${action.id}`" @click="openOutcomes[action.id]=!openOutcomes[action.id]">{{openOutcomes[action.id]?'Hide outcome editor':'Record service outcome'}}</button>
       <div v-if="canManage&&isAuthor&&selected?.plan.status==='active'&&openOutcomes[action.id]" :id="`outcome-editor-${action.id}`"><InterventionOutcomeForm :action="action" :model-value="outcomeData(action)" @update:model-value="forms[outcomeKey(action.id)]=$event" :busy="disabled" :errors="errorsFor(outcomeKey(action.id))" @submit="saveOutcome(action)"/></div>
      </div></article>
      <p v-if="selected?.interventions.length&&!shownServices.length" class="ui-panel p-4 text-sm text-slate-600">No services match the current filters. Clear filters to view all recorded services in this plan.</p>
      <PlanningForm v-if="editable&&selected?.goals.length" id="intervention" title="Plan intervention" v-model="intervention" :fields="interventionFields" :busy="disabled" submit-label="Save intervention" :errors="errorsFor(formKey('intervention'))" @submit="addIntervention"/>
      <p v-if="!selected?.interventions.length" class="ui-panel p-4 text-sm text-slate-600">No interventions recorded. {{editable&&!selected?.goals.length?'Add a goal first.':''}}</p>
     </section>
     <section v-else-if="activeView==='review'&&selected" aria-label="Workflow and formal review" ref="activePanel" tabindex="-1" class="space-y-4">
      <div class="ui-panel p-4 sm:p-5"><h2 class="ui-section-title">Workflow and formal review</h2><p class="ui-muted mt-1">Draft and returned plans remain editable by their author. Activation and completion require a different authorized reviewer.</p><div v-if="selected.plan.returned_at" class="mt-4 rounded-md border border-amber-300 bg-kalinga-warm p-3"><h3 class="text-sm font-semibold text-amber-950">Returned for revision</h3><p class="mt-1 whitespace-pre-wrap text-sm text-amber-950">{{selected.plan.review_comments}}</p></div><FormField id="planning-comments" label="Reviewer comments" hint="A comment is required when returning a plan." class="mt-4"><textarea id="planning-comments" v-model="reviewComments" :disabled="disabled" maxlength="5000" rows="3" class="ui-field"/></FormField><div class="mt-4 flex flex-wrap gap-2"><button v-if="editable" type="button" class="ui-button-primary" :disabled="disabled" @click="ask('for_review','Submit plan for review')">{{selected.plan.status==='returned'?'Revise and resubmit':'Submit for review'}}</button><button v-if="canReview&&!isAuthor&&selected.plan.status==='for_review'" type="button" class="ui-button-primary" :disabled="disabled" @click="ask('active','Activate plan')">Activate plan</button><button v-if="canReview&&!isAuthor&&selected.plan.status==='for_review'" type="button" class="ui-button" :disabled="disabled" @click="ask('returned','Return plan for revision')">Return for revision</button><button v-if="isAuthor&&selected.plan.status==='active'" type="button" class="ui-button-primary" :disabled="disabled" @click="ask('under_review','Request formal review')">Request formal review</button><button v-if="canReview&&!isAuthor&&selected.plan.status==='under_review'" type="button" class="ui-button-primary" :disabled="disabled" @click="ask('completed','Complete plan')">Mark completed</button></div></div>
      <PlanningForm v-if="canReview&&!isAuthor&&selected.plan.status==='under_review'" id="review" title="Record formal review" v-model="review" :fields="reviewFields" :busy="disabled" submit-label="Finalize review" :errors="errorsFor(formKey('review'))" @submit="addReview"/>
      <div class="ui-panel p-4"><h2 class="ui-section-title">Version history</h2><ol class="mt-3 space-y-3"><li v-for="entry in data.plans" :key="entry.plan.id" class="border-l-2 border-brand-300 pl-3 text-sm"><p class="font-semibold text-slate-900">Version {{entry.plan.version}} - {{human(entry.plan.status)}}</p><p class="mt-1 text-slate-600">Plan {{date(entry.plan.plan_date)}} - {{entry.plan.is_current?'Current plan':'Historical / draft'}}</p></li></ol></div>
     </section>
     <section v-else-if="activeView==='continuity'" aria-label="Aftercare and reintegration" ref="activePanel" tabindex="-1" class="space-y-4"><p class="rounded-md border border-sky-200 bg-sky-50 p-3 text-sm leading-6 text-sky-950">Record continuity decisions when applicable. These records do not automatically close or reopen a case.</p><div v-if="canManage" class="grid items-start gap-4 2xl:grid-cols-2"><PlanningForm id="aftercare" title="Aftercare continuity" v-model="forms.aftercare" :fields="aftercareFields" :busy="disabled" submit-label="Save aftercare" :errors="errorsFor('aftercare')" @submit="continuity('aftercare')"/><PlanningForm id="reintegration" title="Reintegration" v-model="forms.reintegration" :fields="reintegrationFields" :busy="disabled" submit-label="Save reintegration" :errors="errorsFor('reintegration')" @submit="continuity('reintegration')"/></div><div class="ui-panel p-4"><h2 class="ui-section-title">Continuity history</h2><div class="mt-3 grid gap-4 md:grid-cols-2"><section><h3 class="text-sm font-semibold text-slate-900">Aftercare</h3><article v-for="record in data.aftercare" :key="record.id" class="mt-3 rounded-md border border-slate-200 p-3 text-sm"><StatusBadge :label="human(record.status)"/><p class="mt-2">{{record.responsible_office||'Office not recorded'}} - follow-up {{date(record.initial_follow_up_at)}}</p></article><p v-if="!data.aftercare.length" class="ui-muted mt-2">None recorded.</p></section><section><h3 class="text-sm font-semibold text-slate-900">Reintegration</h3><article v-for="record in data.reintegration" :key="record.id" class="mt-3 rounded-md border border-slate-200 p-3 text-sm"><StatusBadge :label="human(record.status)"/><p class="mt-2">{{record.responsible_office||'Office not recorded'}} - target {{date(record.target_date)}}</p></article><p v-if="!data.reintegration.length" class="ui-muted mt-2">None recorded.</p></section></div></div></section>
     <section v-else-if="activeView==='handover'&&canTransfer" aria-label="Formal handover" ref="activePanel" tabindex="-1" class="space-y-4"><PlanningForm id="handover" title="Formal handover" description="The case ID stays the same. Cross-LGU handover remains disabled pending approved policy. Membership alone does not grant case access." v-model="forms.transfer" :fields="transferFields" :busy="disabled" submit-label="Create handover draft" :errors="errorsFor('transfer')" @submit="saveTransfer"/><p v-if="!transferCandidates.length" class="ui-muted">No eligible receiving workers are currently available. Review authorized LGU eligibility before completing a handover.</p><article v-for="transfer in data.transfers" :key="transfer.id" class="ui-panel p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="text-sm font-semibold text-slate-900">{{transfer.originating_office}} to {{transfer.receiving_office}}</h3><StatusBadge :label="human(transfer.status)" tone="brand"/></div><p class="ui-muted mt-2">{{transfer.receiving_worker_name||'Receiving worker not recorded'}}</p><p class="mt-2 whitespace-pre-wrap break-words text-sm text-slate-700">{{transfer.reason}}</p><div class="mt-3 flex flex-wrap gap-2"><button v-for="[status,label] in handoverActions(transfer)" :key="status" type="button" :disabled="disabled" class="ui-button" @click="ask(status,label,transfer)">{{label}}</button><button v-if="!['completed','cancelled'].includes(transfer.status)" type="button" :disabled="disabled" class="ui-button" @click="ask('cancelled','Cancel handover',transfer)">Cancel</button></div></article><p v-if="!data.transfers.length" class="ui-panel p-4 text-sm text-slate-600">No handovers recorded.</p></section>
    </div>
   </div>
   <Modal :show="Boolean(pending)" aria-labelledby="planning-change-title" max-width="md" @close="cancelChange" @closed="applyAfterClose"><section class="p-5"><h2 id="planning-change-title" class="text-lg font-semibold text-slate-900">{{pending?.title}}</h2><p class="ui-muted mt-2">Review the selected record and recorded information before changing its workflow status. This records a professional action under your account.</p><div class="mt-5 flex flex-wrap justify-end gap-2"><button type="button" class="ui-button" @click="cancelChange">Not yet</button><button type="button" class="ui-button-primary" @click="applyChange">Confirm status change</button></div></section></Modal>
  </div>
 </AuthenticatedLayout>
</template>
